"""CLI handler functions dispatched by __main__.py."""

import csv
import json
import sqlite3
import sys
from io import StringIO

from invtrack import db


def init(db_path: str) -> None:
    db.init(db_path)


def add_item(db_path: str, sku: str, name: str, qty: int, price: float) -> None:
    if qty < 0:
        raise ValueError("quantity must not be negative")
    if price < 0:
        raise ValueError("price must not be negative")
    try:
        db.add_item(db_path, sku, name, qty, price)
    except sqlite3.IntegrityError:
        raise ValueError(f"duplicate SKU: {sku}")


def get_item(db_path: str, sku: str) -> None:
    item = db.get_item(db_path, sku)
    if item is None:
        raise KeyError(f"SKU not found: {sku}")
    print(json.dumps(item))


def list_items(db_path: str, fmt: str) -> None:
    items = db.list_items(db_path)

    if fmt == "json":
        print(json.dumps(items))

    elif fmt == "csv":
        writer = csv.writer(sys.stdout)
        writer.writerow(["sku", "name", "qty", "price"])
        for item in items:
            writer.writerow([item["sku"], item["name"], item["qty"], item["price"]])

    else:  # table
        if not items:
            print("No items.")
            return
        header = ["SKU", "Name", "Qty", "Price"]
        col_widths = [len(h) for h in header]
        rows: list[list[str]] = []
        for item in items:
            row = [
                str(item["sku"]),
                item["name"],
                str(item["qty"]),
                f"{item['price']:.2f}",
            ]
            rows.append(row)
            for i, cell in enumerate(row):
                col_widths[i] = max(col_widths[i], len(cell))

        fmt_str = "  ".join(f"{{:<{w}}}" for w in col_widths)
        print(fmt_str.format(*header))
        print("-" * len(fmt_str.format(*header)))
        for row in rows:
            print(fmt_str.format(*row))


def adjust_item(db_path: str, sku: str, delta: int) -> None:
    try:
        db.adjust_item(db_path, sku, delta)
    except KeyError as e:
        raise KeyError(f"SKU not found: {sku}") from e
    except ValueError as e:
        raise ValueError(str(e))


def delete_item(db_path: str, sku: str) -> None:
    try:
        db.delete_item(db_path, sku)
    except KeyError as e:
        raise KeyError(f"SKU not found: {sku}") from e


def low_items(db_path: str, threshold: int) -> None:
    items = db.low_items(db_path, threshold)
    if not items:
        print("No low-stock items.")
        return
    header = ["SKU", "Name", "Qty", "Price"]
    col_widths = [len(h) for h in header]
    rows: list[list[str]] = []
    for item in items:
        row = [
            str(item["sku"]),
            item["name"],
            str(item["qty"]),
            f"{item['price']:.2f}",
        ]
        rows.append(row)
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    fmt_str = "  ".join(f"{{:<{w}}}" for w in col_widths)
    print(fmt_str.format(*header))
    print("-" * len(fmt_str.format(*header)))
    for row in rows:
        print(fmt_str.format(*row))


def report_value(db_path: str) -> None:
    total = db.total_value(db_path)
    print(f"{total:.2f}")

import sqlite3


def init(db_path: str) -> None:
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS items (
                sku TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                qty INTEGER NOT NULL CHECK(qty >= 0),
                price REAL NOT NULL CHECK(price >= 0)
            )
        """
        )
        conn.commit()
    finally:
        conn.close()


def add_item(db_path: str, sku: str, name: str, qty: int, price: float) -> None:
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            "INSERT INTO items (sku, name, qty, price) VALUES (?, ?, ?, ?)",
            (sku, name, qty, price),
        )
        conn.commit()
    finally:
        conn.close()


def get_item(db_path: str, sku: str) -> dict | None:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute(
            "SELECT sku, name, qty, price FROM items WHERE sku = ?", (sku,)
        )
        row = cursor.fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    return {"sku": row[0], "name": row[1], "qty": row[2], "price": row[3]}


def list_items(db_path: str) -> list[dict]:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute("SELECT sku, name, qty, price FROM items")
        rows = cursor.fetchall()
    finally:
        conn.close()
    return [{"sku": r[0], "name": r[1], "qty": r[2], "price": r[3]} for r in rows]


def adjust_item(db_path: str, sku: str, delta: int) -> None:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute("SELECT qty FROM items WHERE sku = ?", (sku,))
        row = cursor.fetchone()
        if row is None:
            raise KeyError(f"SKU not found: {sku}")
        new_qty = row[0] + delta
        if new_qty < 0:
            raise ValueError("quantity would go below zero")
        conn.execute("UPDATE items SET qty = ? WHERE sku = ?", (new_qty, sku))
        conn.commit()
    finally:
        conn.close()


def delete_item(db_path: str, sku: str) -> None:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute("DELETE FROM items WHERE sku = ?", (sku,))
        if cursor.rowcount == 0:
            raise KeyError(f"SKU not found: {sku}")
        conn.commit()
    finally:
        conn.close()


def low_items(db_path: str, threshold: int) -> list[dict]:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute(
            "SELECT sku, name, qty, price FROM items WHERE qty < ?", (threshold,)
        )
        rows = cursor.fetchall()
    finally:
        conn.close()
    return [{"sku": r[0], "name": r[1], "qty": r[2], "price": r[3]} for r in rows]


def total_value(db_path: str) -> float:
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.execute("SELECT COALESCE(SUM(qty * price), 0.0) FROM items")
        result = cursor.fetchone()[0]
    finally:
        conn.close()
    return float(result)
